/**
 * Loader for the JSON vectors generated by `contracts/engine/tests/vectors.rs`. The files are read
 * from the engine crate (never copied) and decoded into the SDK's bigint types; every integer that
 * can exceed 2^53 is a decimal string in the JSON, the others are JSON numbers.
 */

import { readFileSync } from "node:fs";

import type { AdvanceAsk, Fill, Order, Pricing } from "../src/clearing.js";
import type { SablierLinearParams, StreamflowParams } from "../src/unlock.js";

const VECTORS_DIR = new URL("../../../contracts/engine/tests/vectors/", import.meta.url);

/** Expected fills of a cleared round; `fee` is present on the buying side only. */
export interface ExpectedFill extends Fill {
  readonly fee: bigint | undefined;
}

export interface TenderExpected {
  readonly price: bigint;
  readonly volume: bigint;
  readonly asks: readonly ExpectedFill[];
  readonly charged: bigint;
  readonly fee: bigint;
  readonly refund: bigint;
}

export interface UniformExpected {
  readonly price: bigint;
  readonly volume: bigint;
  readonly bids: readonly ExpectedFill[];
  readonly asks: readonly ExpectedFill[];
  readonly notional: bigint;
}

export type Expected<T> = { readonly outcome: "no_crossing" } | ({ readonly outcome: "cleared" } & T);

export interface TenderCase {
  readonly name: string;
  readonly round: "tender";
  readonly input: {
    readonly pricing: Pricing;
    readonly budget: bigint;
    readonly maxPrice: bigint;
    readonly asks: readonly Order[];
  };
  readonly expected: Expected<TenderExpected>;
}

export interface ExitCase {
  readonly name: string;
  readonly round: "exit";
  readonly input: {
    readonly pricing: Pricing;
    readonly bids: readonly Order[];
    readonly asks: readonly Order[];
  };
  readonly expected: Expected<UniformExpected>;
}

export interface AdvanceCase {
  readonly name: string;
  readonly round: "advance";
  readonly input: {
    readonly tokenDecimals: number;
    readonly ask: AdvanceAsk;
    readonly bids: readonly Order[];
  };
  readonly expected: Expected<UniformExpected>;
}

export type ClearingCase = TenderCase | ExitCase | AdvanceCase;

export interface ClearingVectors {
  readonly feeBps: bigint;
  readonly bpsDenominator: bigint;
  readonly cases: readonly ClearingCase[];
}

export interface LinearClassJson {
  readonly kind: "linear";
  readonly start: bigint;
  readonly cliff: bigint;
  readonly end: bigint;
  readonly granularity: bigint;
  readonly startUnlock: bigint;
  readonly cliffUnlock: bigint;
  readonly total: bigint;
  readonly minDeposit: bigint;
  readonly margin: bigint;
}

export interface SteppedClassJson {
  readonly kind: "stepped";
  readonly start: bigint;
  readonly end: bigint;
  readonly period: bigint;
  readonly cliffAmount: bigint;
  readonly amountPerPeriod: bigint;
  readonly total: bigint;
}

export interface SablierCase {
  readonly name: string;
  readonly input: SablierLinearParams & { readonly tokenDecimals: number };
  readonly class: LinearClassJson;
  readonly points: readonly { readonly t: bigint; readonly streamed: bigint; readonly fraction: bigint }[];
}

export interface StreamflowCase {
  readonly name: string;
  readonly input: StreamflowParams;
  readonly class: SteppedClassJson;
  readonly points: readonly { readonly t: bigint; readonly unlocked: bigint; readonly fraction: bigint }[];
}

export interface AccrualCase {
  readonly balance: bigint;
  readonly from: bigint;
  readonly to: bigint;
  readonly accrual: bigint;
}

export interface UnlockVectors {
  readonly one: bigint;
  readonly sablierLinear: readonly SablierCase[];
  readonly streamflow: readonly StreamflowCase[];
  readonly accrual: readonly AccrualCase[];
}

export function loadClearingVectors(): ClearingVectors {
  const root = record(readJson("clearing.json"), "clearing");
  return {
    feeBps: big(root, "fee_bps"),
    bpsDenominator: big(root, "bps_denominator"),
    cases: list(root, "cases").map(clearingCase),
  };
}

export function loadUnlockVectors(): UnlockVectors {
  const root = record(readJson("unlock.json"), "unlock");
  return {
    one: big(root, "one"),
    sablierLinear: list(root, "sablier_linear").map(sablierCase),
    streamflow: list(root, "streamflow").map(streamflowCase),
    accrual: list(root, "accrual").map((value) => {
      const item = record(value, "accrual case");
      return {
        balance: big(item, "balance"),
        from: big(item, "from"),
        to: big(item, "to"),
        accrual: big(item, "accrual"),
      };
    }),
  };
}

function readJson(file: string): unknown {
  return JSON.parse(readFileSync(new URL(file, VECTORS_DIR), "utf8")) as unknown;
}

type Json = Record<string, unknown>;

function record(value: unknown, path: string): Json {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError(`${path}: expected an object`);
  }
  return value as Json;
}

function list(parent: Json, key: string): unknown[] {
  const value = parent[key];
  if (!Array.isArray(value)) {
    throw new TypeError(`${key}: expected an array`);
  }
  return value as unknown[];
}

function big(parent: Json, key: string): bigint {
  const value = parent[key];
  if (typeof value === "string" && /^[0-9]+$/.test(value)) {
    return BigInt(value);
  }
  if (typeof value === "number" && Number.isSafeInteger(value)) {
    return BigInt(value);
  }
  throw new TypeError(`${key}: expected a decimal string or a safe integer`);
}

function small(parent: Json, key: string): number {
  const value = parent[key];
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    throw new TypeError(`${key}: expected a safe integer`);
  }
  return value;
}

function text(parent: Json, key: string): string {
  const value = parent[key];
  if (typeof value !== "string") {
    throw new TypeError(`${key}: expected a string`);
  }
  return value;
}

function orders(parent: Json, key: string): Order[] {
  return list(parent, key).map((value) => {
    const order = record(value, key);
    return { id: big(order, "id"), qty: big(order, "qty"), price: big(order, "price") };
  });
}

function fills(parent: Json, key: string): ExpectedFill[] {
  return list(parent, key).map((value) => {
    const fill = record(value, key);
    return {
      id: big(fill, "id"),
      qty: big(fill, "qty"),
      cash: big(fill, "cash"),
      fee: "fee" in fill ? big(fill, "fee") : undefined,
    };
  });
}

function pricing(parent: Json): Pricing {
  const value = record(parent["pricing"], "pricing");
  return { lockedFractionE18: big(value, "locked_fraction_e18"), tokenDecimals: small(value, "token_decimals") };
}

function tenderExpected(value: Json): Expected<TenderExpected> {
  if (text(value, "outcome") === "no_crossing") {
    return { outcome: "no_crossing" };
  }
  return {
    outcome: "cleared",
    price: big(value, "price"),
    volume: big(value, "volume"),
    asks: fills(value, "asks"),
    charged: big(value, "charged"),
    fee: big(value, "fee"),
    refund: big(value, "refund"),
  };
}

function uniformExpected(value: Json): Expected<UniformExpected> {
  if (text(value, "outcome") === "no_crossing") {
    return { outcome: "no_crossing" };
  }
  return {
    outcome: "cleared",
    price: big(value, "price"),
    volume: big(value, "volume"),
    bids: fills(value, "bids"),
    asks: fills(value, "asks"),
    notional: big(value, "notional"),
  };
}

function clearingCase(value: unknown): ClearingCase {
  const item = record(value, "case");
  const name = text(item, "name");
  const input = record(item["input"], "input");
  const expected = record(item["expected"], "expected");
  const round = text(item, "round");
  switch (round) {
    case "tender":
      return {
        name,
        round,
        input: {
          pricing: pricing(input),
          budget: big(input, "budget"),
          maxPrice: big(input, "max_price"),
          asks: orders(input, "asks"),
        },
        expected: tenderExpected(expected),
      };
    case "exit":
      return {
        name,
        round,
        input: { pricing: pricing(input), bids: orders(input, "bids"), asks: orders(input, "asks") },
        expected: uniformExpected(expected),
      };
    case "advance": {
      const ask = record(input["ask"], "ask");
      return {
        name,
        round,
        input: {
          tokenDecimals: small(input, "token_decimals"),
          ask: {
            id: big(ask, "id"),
            claim: big(ask, "claim"),
            reserve: big(ask, "reserve"),
            minFill: big(ask, "min_fill"),
          },
          bids: orders(input, "bids"),
        },
        expected: uniformExpected(expected),
      };
    }
    default:
      throw new TypeError(`${name}: unknown round ${round}`);
  }
}

function sablierCase(value: unknown): SablierCase {
  const item = record(value, "sablier case");
  const input = record(item["input"], "input");
  const klass = record(item["class"], "class");
  if (text(klass, "kind") !== "linear") {
    throw new TypeError("sablier case: expected a linear class");
  }
  return {
    name: text(item, "name"),
    input: {
      start: big(input, "start"),
      cliff: big(input, "cliff"),
      end: big(input, "end"),
      granularity: big(input, "granularity"),
      startUnlock: big(input, "start_unlock"),
      cliffUnlock: big(input, "cliff_unlock"),
      deposited: big(input, "deposited"),
      tokenDecimals: small(input, "token_decimals"),
    },
    class: {
      kind: "linear",
      start: big(klass, "start"),
      cliff: big(klass, "cliff"),
      end: big(klass, "end"),
      granularity: big(klass, "granularity"),
      startUnlock: big(klass, "start_unlock"),
      cliffUnlock: big(klass, "cliff_unlock"),
      total: big(klass, "total"),
      minDeposit: big(klass, "min_deposit"),
      margin: big(klass, "margin"),
    },
    points: list(item, "points").map((point) => {
      const p = record(point, "point");
      return { t: big(p, "t"), streamed: big(p, "streamed"), fraction: big(p, "fraction") };
    }),
  };
}

function streamflowCase(value: unknown): StreamflowCase {
  const item = record(value, "streamflow case");
  const input = record(item["input"], "input");
  const klass = record(item["class"], "class");
  if (text(klass, "kind") !== "stepped") {
    throw new TypeError("streamflow case: expected a stepped class");
  }
  return {
    name: text(item, "name"),
    input: {
      startTime: big(input, "start_time"),
      cliff: big(input, "cliff"),
      cliffAmount: big(input, "cliff_amount"),
      period: big(input, "period"),
      amountPerPeriod: big(input, "amount_per_period"),
      netAmountDeposited: big(input, "net_amount_deposited"),
      endTime: big(input, "end_time"),
    },
    class: {
      kind: "stepped",
      start: big(klass, "start"),
      end: big(klass, "end"),
      period: big(klass, "period"),
      cliffAmount: big(klass, "cliff_amount"),
      amountPerPeriod: big(klass, "amount_per_period"),
      total: big(klass, "total"),
    },
    points: list(item, "points").map((point) => {
      const p = record(point, "point");
      return { t: big(p, "t"), unlocked: big(p, "unlocked"), fraction: big(p, "fraction") };
    }),
  };
}
